-- Expand DAEHAN grade-3 new-character example-word coverage (batch 3).
with words(word,reading,meaning,child_explanation,chars) as (values
('비밀','비밀','남에게 알리지 않는 일','다른 사람에게 알려지지 않도록 숨겨 둔 일이나 내용',array['秘','密']),('사립','사립','개인이 세움','개인이나 민간 단체가 세워 운영하는 것',array['私','立']),('사격','사격','목표를 향해 쏨','정해진 목표를 향해 총이나 활 등을 쏘는 것',array['射','的']),('상처','상처','다쳐서 생긴 자리','몸이나 마음이 다쳐 아프게 된 자리나 흔적',array['傷','處']),('상강','상강','서리가 내리는 때','가을이 깊어져 서리가 내리기 시작하는 절기',array['霜','降']),('상고','상고','높이 여기고 존중함','가치 있는 것을 높이 여기고 중요하게 생각하는 것',array['尙','高']),('상실','상실','가지고 있던 것을 잃음','가지고 있던 것이나 능력을 잃어버리는 것',array['喪','失']),('상형','상형','모양을 본떠 나타냄','사물의 생긴 모양을 본떠 글자나 그림으로 나타내는 것',array['象','形']),('서한','서한','더위와 추위','더운 기운과 추운 기운을 함께 이르는 말',array['暑','寒']),('애석','애석','아깝고 서운함','소중한 것을 잃거나 놓쳐 아깝고 서운하게 느끼는 것',array['愛','惜']),('석금','석금','옛날과 오늘','옛날과 오늘날을 함께 이르는 말',array['昔','今']),('손해','손해','이익을 잃거나 피해를 봄','재산이나 이익이 줄거나 피해를 입는 것',array['損','害']),('수인','수인','누구인 사람','어떤 사람인지 분명하지 않을 때 누구를 가리키는 말',array['誰','人']),('수요','수요','꼭 필요로 함','사람들이 어떤 물건이나 서비스를 필요로 하는 정도',array['須','要']),('수명','수명','살아 있는 기간','사람이나 생물이 태어나서 살아가는 기간',array['壽','命']),('수연','수연','비록 그러하지만','앞의 사실을 인정하면서 뒤의 다른 내용을 이어 말하는 표현',array['雖','然']),('수재','수재','재주가 뛰어난 사람','머리가 좋고 재주가 뛰어난 사람',array['秀','才']),('숙녀','숙녀','품행이 단정한 여성','예의 바르고 품행이 단정한 여성을 이르는 말',array['淑','女']),('숙부','숙부','아버지의 남동생','아버지보다 나이가 어린 남자 형제를 이르는 말',array['叔','父']),('숭경','숭경','높여 공경함','훌륭한 사람이나 대상을 높이고 공경하는 것',array['崇','敬']),('승차','승차','차에 탐','자동차나 기차 같은 탈것에 올라타는 것',array['乘','車']),('시행','시행','실제로 행함','정해진 계획이나 제도를 실제로 실행하는 것',array['施','行']),('심해','심해','깊은 바다','햇빛이 잘 닿지 않을 만큼 매우 깊은 바다',array['深','海']),('심대','심대','매우 크고 중요함','영향이나 정도가 아주 크고 중요한 상태',array['甚','大']),('아국','아국','우리나라','자기 나라를 가리키는 옛 한자말',array['我','國'])
), upserted as (insert into public.hanja_words(word,reading,meaning,child_explanation,content_status,source_note) select word,reading,meaning,child_explanation,'PUBLISHED','3급 신규 예시어 보강 3차 · 앱 자체 쉬운 뜻풀이 · 2026-10-06' from words on conflict(word,reading,meaning) do update set child_explanation=excluded.child_explanation,content_status='PUBLISHED',source_note=excluded.source_note returning id,word,reading,meaning)
insert into public.hanja_word_map(word_id,hanja_id,position) select hw.id,h.id,u.ord::integer from words w join upserted hw on hw.word=w.word and hw.reading=w.reading and hw.meaning=w.meaning cross join lateral unnest(w.chars) with ordinality u(ch,ord) join public.hanja h on h.character=u.ch on conflict do nothing;